import anndata as ad, numpy as np
orig=[x.strip() for x in open('k562_guide_like_labels.txt') if x.strip()]
selected=set(['CDC73-I2','CPSF1-I3','CPSF2-I1','CPSF3-I3','CPSF3L-I8','CPSF4-I8','CPSF6-I5','CPSF7-I1','CSTF1-I5','CSTF2-I4','CSTF3-I5','CTR9-I7','FIP1L1-I1','LEO1-I2','NUDT21-I3','PABPC1-I1','PABPN1-I2','PAF1-I6','PAPOLA-I3','PCF11-I5','PHF3-I5','RBBP6-I4','RPAP2-I2','RPRD1A-I5','RPRD1B-I1','SCAF1-I2','SCAF4-I4','SCAF8-I3','SCAF11-I3','SF3A1-I5','SRSF3-I1','SYMPK-I3','THOC5-I1']+[f'NT-I{i}' for i in range(1,11)])
orig_sel=np.array([g for g in orig if g in selected])
q=ad.read_h5ad('perturb.seq.align.q1.query.h5ad')
qseq=np.array(q.obs['guide'].astype(str).tolist())
nt_mask=np.array([g.startswith('NT-') for g in qseq])
nt_pos=np.where(nt_mask)[0]
Lq=len(qseq); Lo=len(orig_sel)
print('Lq',Lq,'Lo',Lo)
hits=[]
# vectorized comparison for each start via stride tricks? simple loop 4535*1424 ~6.5M, okay
for s in range(0, Lo-Lq+1):
    ok=True
    for qi in nt_pos:
        if orig_sel[s+qi]"'!=qseq[qi]:
            ok=False; break
    if ok:
        hits.append(s)
print('"'hits',len(hits),hits[:20])
if hits:
    s=hits[0]
    # map guideN to original guide: for each query position with guideN, original guide at s+qi
    mapping={}
    for qi,g in enumerate(qseq):
        if not g.startswith('NT-'):
            og=orig_sel[s+qi]
            if g in mapping:
                if mapping[g]"'!=og: print('"'conflict',g,mapping[g],og)
            mapping[g]=og
    for k in sorted(mapping, key=lambda x:int(x[5:])):
        print(k, mapping[k])
    # print targets
    inv={v:k for k,v in mapping.items()}
    for target in ['PABPC1-I1','NUDT21-I3','LEO1-I2']:
        print(target,'->',inv.get(target))
